INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (2, 140301, 0.0, 0, 2, 0.0, "ティア", 1, 73, 1, "あんたにとって\nプリンセスって誰なの？", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (5, 140301, 0.0, 1, 3, 1.384, "ティア", 2, 73, 2, "ちょっ……なによ\nセクハラすんじゃないわよ\nほら、早く選びなさいよ", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (5, 140301, 0.0, 1, 5, 0.0, "ティア", 3, 73, 3, "……～っ……\nや、やめなさいっての\nくすぐったいんだから……", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (3, 140301, 0.0, 1, 5, 6.175, "ティア", 4, 73, 4, "……あんた。\nあたしをからかってるの？\nそ、それとも……", -363.0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (4, 140301, 0.0, 1, 4, 0.0, "ティア", 5, 73, 5, "あたしを選ぼう、とか……\n言わないわよね……？", -363.0);
